//https://leetcode.com/problems/find-the-length-of-the-longest-common-prefix/description/?envType=daily-question&envId=2026-05-21


using System.Diagnostics;

public class Solution
{
    public int LongestCommonPrefix(int[] arr1, int[] arr2)
    {
        //var usedValues = new Dictionary<int, HashSet<int>>();

        int theBiggestLength = 0;

        for (int i = 0; i < arr1.Length; i++)
        {
            for (int j = 0; j < arr2.Length; j++)
            {
                int valueToCompare_1 = arr1[i];
                int valueToCompare_2 = arr2[j];


                var valueToCompare_1_Length = GetLength(valueToCompare_1);
                var valueToCompare_2_Length = GetLength(valueToCompare_2);

                int biggerValue = valueToCompare_1_Length >= valueToCompare_2_Length ? valueToCompare_1 : valueToCompare_2;
                int smallerValue = valueToCompare_1_Length >= valueToCompare_2_Length ? valueToCompare_2 : valueToCompare_1;
                int lengthDifference = Math.Abs(valueToCompare_1_Length - valueToCompare_2_Length);

                int upgradedBiggerValue = biggerValue / ((lengthDifference != 0 ? (int)Math.Pow(10, lengthDifference) : 1));

                int smallTemp = smallerValue;
                int biggerTemp = upgradedBiggerValue;
                while (smallTemp != biggerTemp)
                {
                    smallTemp /= 10;
                    biggerTemp /= 10;
                }

                int length = GetLength(biggerTemp);

                if (theBiggestLength < length)
                {
                    theBiggestLength = length;
                }
            }
        }

        return theBiggestLength;
    }

    private int GetLength(int number)
    {
        return number == 0 ? 0 : (int)Math.Log10(Math.Abs(number)) + 1;
    }
}


public class Solution2
{
    public int LongestCommonPrefix(int[] arr1, int[] arr2)
    {
        var hashSet1 = GetUniqueDistributedValues(arr1);
        var hashSet2 = GetUniqueDistributedValues(arr2);

        int biggestLength = 0;

        foreach (var item1 in hashSet1)
        {
            if (hashSet2.Contains(item1))
            {
                int length = GetLength(item1);
                if (length > biggestLength)
                {
                    biggestLength = length;
                }
            }
        }

        return biggestLength;
    }

    private static HashSet<int> GetUniqueDistributedValues(int[] arr)
    {
        var hashSet = new HashSet<int>();
        for (int i = 0; i < arr.Length; i++)
        {
            hashSet.Add(arr[i]);

            int fullNumber = arr[i];
            while (fullNumber != 0)
            {
                fullNumber /= 10;
                hashSet.Add(fullNumber);
            }
        }
        hashSet.Remove(0);
        return hashSet;
    }
    private int GetLength(int number)
    {
        return number == 0 ? 0 : (int)Math.Log10(Math.Abs(number)) + 1;
    }
}

public class Solution3
{
    public int LongestCommonPrefix(int[] arr1, int[] arr2)
    {
        var hashSet1 = GetUniqueDistributedValues(arr1);

        int theBiggestLength = 0;

        for (int i = 0; i < arr2.Length; i++)
        {
            int fullNumber = arr2[i];

            if (hashSet1.Contains(fullNumber) && fullNumber != 0)
            {
                int length = GetLength(fullNumber);
                if (length > theBiggestLength)
                {
                    theBiggestLength = length;
                }
            }
           
            while (fullNumber != 0)
            {
                fullNumber /= 10;
                if (hashSet1.Contains(fullNumber) && fullNumber != 0)
                {
                    int length = GetLength(fullNumber);
                    if (length > theBiggestLength)
                    {
                        theBiggestLength = length;
                    }
                }
            }
        }


        return theBiggestLength;
    }

    private static HashSet<int> GetUniqueDistributedValues(int[] arr)
    {
        var hashSet = new HashSet<int>();
        for (int i = 0; i < arr.Length; i++)
        {
            hashSet.Add(arr[i]);

            int fullNumber = arr[i];
            while (fullNumber != 0)
            {
                fullNumber /= 10;
                hashSet.Add(fullNumber);
            }
        }
        hashSet.Remove(0);
        return hashSet;
    }
    private int GetLength(int number)
    {
        return number == 0 ? 0 : (int)Math.Log10(Math.Abs(number)) + 1;
    }
}


